INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "クローチェ", 1, 1, 1.47, "2023/09/22 14:59:59", 2, 2002, "2023/06/30 12:00:00", 10001, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", -470, 1, 126401);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "クローチェ", 2, 1, 2.15, "2023/09/22 14:59:59", 1, 2002, "2023/06/30 12:00:00", 10002, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", -470, 2, 126401);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ライラエル", 1, 1, 0, "2023/09/22 14:59:59", 2, 2002, "2023/06/30 12:00:00", 10003, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", -470, 2, 126501);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ライラエル", 2, 1, 0, "2023/09/22 14:59:59", 1, 2002, "2023/06/30 12:00:00", 10004, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", -470, 1, 126501);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "リンド", 1, 2, 0, "2023/12/22 14:59:59", 2, 2002, "2023/09/15 15:00:00", 10005, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", -470, 2, 127702);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "リンド", 2, 2, 0, "2023/12/22 14:59:59", 2, 2002, "2023/09/15 15:00:00", 10006, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", -470, 2, 127702);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ヴルム", 1, 2, 0, "2023/12/22 14:59:59", 1, 2002, "2023/09/15 15:00:00", 10007, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", -470, 1, 127802);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ヴルム", 2, 2, 6.5, "2023/12/22 14:59:59", 1, 2002, "2023/09/15 15:00:00", 10008, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", -470, 2, 127802);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "アネモネ", 1, 3, 0, "2024/03/22 14:59:59", 1, 2002, "2023/12/15 15:00:00", 10009, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", -470, 2, 129602);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "アネモネ", 2, 3, 0, "2024/03/22 14:59:59", 1, 2002, "2023/12/15 15:00:00", 10010, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", -470, 2, 129602);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ネフィ=ネラ", 1, 3, 0, "2024/03/22 14:59:59", 1, 2002, "2023/12/15 15:00:00", 10011, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", -470, 1, 129701);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ネフィ=ネラ", 2, 3, 6.2, "2024/03/22 14:59:59", 1, 2002, "2023/12/15 15:00:00", 10012, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", -470, 2, 129701);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "カノン", 1, 4, 3.1, "2024/06/22 14:59:59", 5, 2002, "2024/03/15 15:00:00", 10013, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", -470, 3, 130301);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "カノン", 2, 4, 6.15, "2024/06/22 14:59:59", 2, 2002, "2024/03/15 15:00:00", 10014, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", -470, 3, 130301);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ナーナ", 1, 4, 0, "2024/06/22 14:59:59", 2, 2002, "2024/03/15 15:00:00", 10015, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", -470, 2, 130401);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ナーナ", 2, 4, 3.35, "2024/06/22 14:59:59", 1, 2002, "2024/03/15 15:00:00", 10016, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", -470, 2, 130401);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ホウオウ", 1, 5, 0, "2024/09/22 14:59:59", 1, 2002, "2024/06/15 15:00:00", 10017, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", -470, 1, 130502);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ホウオウ", 2, 5, 3.18, "2024/09/22 14:59:59", 1, 2002, "2024/06/15 15:00:00", 10018, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", -470, 2, 130502);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ホウオウ", 3, 5, 0, "2024/09/22 14:59:59", 4, 2002, "2024/06/15 15:00:00", 10019, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", -470, 4, 130503);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ネア", 1, 5, 4.9, "2024/09/22 14:59:59", 2, 2002, "2024/06/15 15:00:00", 10020, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", -470, 1, 123301);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ネア", 2, 5, 4.8, "2024/09/22 14:59:59", 2, 2002, "2024/06/15 15:00:00", 10021, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", -470, 1, 123301);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "カリザ", 1, 6, 4.922, "2024/12/22 14:59:59", 1, 2002, "2024/09/15 15:00:00", 10022, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", -470, 3, 133301);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "カリザ", 2, 6, 9.638, "2024/12/22 14:59:59", 5, 2002, "2024/09/15 15:00:00", 10023, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", -470, 3, 133301);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ミーア", 1, 6, 2.88, "2024/12/22 14:59:59", 2, 2002, "2024/09/15 15:00:00", 10024, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", -470, 1, 133401);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ミーア", 2, 6, 4.818, "2024/12/22 14:59:59", 1, 2002, "2024/09/15 15:00:00", 10025, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", -470, 5, 133401);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "グレイス", 1, 7, 1.78, "2025/03/22 14:59:59", 1, 2002, "2024/12/15 15:00:00", 10026, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", -470, 2, 133002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "グレイス", 2, 7, 6.15, "2025/03/22 14:59:59", 7, 2002, "2024/12/15 15:00:00", 10027, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", -470, 1, 133002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ヴァイオレット", 1, 7, 4.28, "2025/03/22 14:59:59", 2, 2002, "2024/12/15 15:00:00", 10028, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", -470, 6, 133102);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ヴァイオレット", 2, 7, 0, "2025/03/22 14:59:59", 1, 2002, "2024/12/15 15:00:00", 10029, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", -470, 1, 133102);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ルルィ", 1, 8, 5.53, "2025/06/23 14:59:59", 1, 2002, "2025/03/15 15:00:00", 10030, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", -470, 2, 136902);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ルルィ", 2, 8, 6.05, "2025/06/23 14:59:59", 7, 2002, "2025/03/15 15:00:00", 10031, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", -470, 9, 136902);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "デュラン", 1, 8, 0, "2025/06/23 14:59:59", 1, 2002, "2025/03/15 15:00:00", 10032, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", -470, 2, 137001);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "デュラン", 2, 8, 0, "2025/06/23 14:59:59", 1, 2002, "2025/03/15 15:00:00", 10033, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", -470, 2, 137001);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "サツキ", 1, 9, 0, "2025/09/23 14:59:59", 2, 2002, "2025/06/16 15:00:00", 10034, "おう\n好きなもん持ってきな", -470, 2, 135902);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "サツキ", 2, 9, 4.935, "2025/09/23 14:59:59", 6, 2002, "2025/06/16 15:00:00", 10035, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", -470, 1, 135902);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ユキノ", 1, 9, 7.441, "2025/09/23 14:59:59", 5, 2002, "2025/06/16 15:00:00", 10036, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", -470, 2, 135802);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ユキノ", 2, 9, 0, "2025/09/23 14:59:59", 7, 2002, "2025/06/16 15:00:00", 10037, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", -470, 7, 135802);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "クルル", 1, 10, 2.295, "2025/12/22 14:59:59", 2, 2002, "2025/09/16 15:00:00", 10038, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", -470, 2, 130901);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "クルル", 2, 10, 6.281, "2025/12/22 14:59:59", 6, 2002, "2025/09/16 15:00:00", 10039, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", -470, 1, 130901);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ヴォルガーノ", 1, 10, 5.549, "2025/12/22 14:59:59", 1, 2002, "2025/09/16 15:00:00", 10040, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", -470, 2, 137701);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ヴォルガーノ", 2, 10, 2.64, "2025/12/22 14:59:59", 6, 2002, "2025/09/16 15:00:00", 10041, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", -470, 3, 137701);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ライラエル", 1, 11, 7.642, "2026/03/23 11:59:59", 4, 2002, "2025/12/15 15:00:00", 10042, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", -470, 7, 132801);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ライラエル", 2, 11, 0, "2026/03/23 11:59:59", 1, 2002, "2025/12/15 15:00:00", 10043, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", -470, 1, 132802);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "クローチェ", 1, 11, 0, "2026/03/23 11:59:59", 1, 2002, "2025/12/15 15:00:00", 10044, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", -470, 1, 134502);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "クローチェ", 2, 11, 3.72, "2026/03/23 11:59:59", 1, 2002, "2025/12/15 15:00:00", 10045, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", -470, 2, 134501);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ネフィ＝ネラ", 1, 12, 4.991, "2026/06/22 11:59:59", 1, 2002, "2026/03/16 12:00:00", 10046, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", -470, 2, 138201);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ネフィ＝ネラ", 2, 12, 3.877, "2026/06/22 11:59:59", 4, 2002, "2026/03/16 12:00:00", 10047, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", -470, 1, 138201);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "アラクネ", 1, 12, 1.71, "2026/06/22 11:59:59", 6, 2002, "2026/03/16 12:00:00", 10048, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", -470, 4, 136001);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "アラクネ", 2, 12, 5.32, "2026/06/22 11:59:59", 2, 2002, "2026/03/16 12:00:00", 10049, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", -470, 5, 136001);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "アネモネ", 1, 13, 3.727, "2026/09/22 11:59:59", 4, 2002, "2026/06/15 12:00:00", 10050, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", -470, 9, 135401);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "アネモネ", 2, 13, 7.213, "2026/09/22 11:59:59", 9, 2002, "2026/06/15 12:00:00", 10051, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", -470, 7, 135401);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "クリア", 1, 13, 1.874, "2026/09/22 11:59:59", 2, 2002, "2026/06/15 12:00:00", 10052, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", -470, 1, 135301);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "クリア", 2, 13, 0, "2026/09/22 11:59:59", 2, 2002, "2026/06/15 12:00:00", 10053, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", -470, 2, 135301);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ヴァイオレット", 1, 14, 4.215, "2026/12/22 11:59:59", 1, 2002, "2026/09/15 12:00:00", 10054, "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", -470, 2, 138001);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "ヴァイオレット", 2, 14, 0, "2026/12/22 11:59:59", 4, 2002, "2026/09/15 12:00:00", 10055, "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", -470, 4, 138001);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "グレイス", 1, 14, 5.477, "2026/12/22 11:59:59", 1, 2002, "2026/09/15 12:00:00", 10056, "何故かいかがわしいお店と\n勘違いされるんですよね\n騎士氏も？　ヤダへんふし", -470, 6, 138901);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (0, "グレイス", 2, 14, 5.743, "2026/12/22 11:59:59", 1, 2002, "2026/09/15 12:00:00", 10057, "どうも。グレイスちゃん\n客寄せバージョンですぴょん\n一名様ごあんな～い", -470, 2, 138901);
